overrides.style:
Menu, Dropdown, Popup, Dialog { border-radius: 22px; border: 1px solid var(--accent-soft); }
Sheet { border-radius: 28px 28px 0 0; border: 1px solid var(--accent-soft); }
SearchField#chats, SearchField#icons, TextField, Composer::field { border-radius: 20px; }
Fab { border-radius: 14px; }
IconTile[icon="theme"], IconTile[icon="store"] { border-radius: 14px; background: var(--accent-soft); color: var(--ink); }
